// ===== Format Answer: نتیجه کوئری ← جدول Markdown + نمودار (تصویر QuickChart) برای Open WebUI =====
// ورودی:  ردیف‌های نتیجه کوئری؛ سوال (Webhook)، SQL و فکر مدل (Security)، اجازه‌ها (AuthCheck)
// خروجی:  { answer }؛ در حالت ارزیابی (بنچمارک) ردیف‌ها، SQL و جدول‌های prompt هم برمی‌گردند
// مراحل:  ۱. جدول Markdown   ۲. کدام ستون عدد و کدام برچسب   ۳. نوع نمودار   ۴. تنظیمات Chart.js   ۵. آدرس تصویر
//         ۶. یادداشت‌های Obsidian که جواب از آن‌ها آمد (جدول‌ها و معیارهای prompt)
// بعد از این نود: Respond to Webhook (جواب کاربر) و Obsidian note (یادداشت ✅/❌ برای بازبین‌ها).

// ---------- تنظیمات ----------
const CFG = {
  AUTO_CHART: true,   // نمودار بدون درخواست صریح کاربر هم کشیده شود
  MAX_TABLE:  50,     // حداکثر ردیف نمایشی در جدول
  MAX_CHART:  20,     // سقف تعداد نقطه در نمودار (بر اساس نوع نمودار پایین‌تر می‌آید)
  CHART_LIMITS: { pie: 8, line: 15, bar: 20 },
  ROW_CAP:    200,    // همان POLICY.ROW_CAP در Security: نتیجه‌ای با این تعداد ردیف احتمالاً بریده شده است
  // آدرس سرویس quickchart آن‌طور که مرورگر کاربر می‌بیند (تصویر نمودار را مرورگر کاربر باز می‌کند، نه n8n).
  // localhost فقط روی خود سرور کار می‌کند؛ برای کاربران شبکه نام یا IP سرور را بگذارید، مثلاً http://172.16.55.20:3001
  CHART_BASE_URL: 'http://localhost:3001',
  // پالت رنگ برای اینکه هر میله/برش رنگ خودش را داشته باشد، نه یک رنگ یکنواخت
  PALETTE: ['#4E79A7', '#F28E2B', '#E15759', '#76B7B2', '#59A14F', '#EDC948',
            '#B07AA1', '#FF9DA7', '#9C755F', '#BAB0AC', '#86BCB6', '#D37295'],
};

// ---------- آداپتر n8n: تنها جایی که $input و $('...') خوانده می‌شود ----------
function readN8nInputs() {
  const json = name => { try { return $(name).first().json || {}; } catch (e) { return {}; } };
  return {
    // نتیجه خالی ممکن است به‌شکل یک آیتم خالی {} برسد؛ آن را ردیف حساب نمی‌کنیم
    rows: $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0),
    question: $('Webhook').first().json.body.question || '',
    sec: $('Security').first().json,
    can: json('AuthCheck').can || {},
    // جدول‌هایی که به مدل داده شد؛ runner بنچمارک با expected_entities مقایسه می‌کند تا «جدول لازم به prompt
    // نرسید» (retrieval) از «SQL غلط» جدا شمرده شود
    selectedEntities: json('BuildPrompt').selectedEntities || [],
    metrics: (json('BuildPrompt').retrieval || {}).metrics || [],
  };
}

// ---------- کمکی‌ها ----------
// متنی که | یا خط جدید دارد جدول Markdown را می‌شکند
const mdSafe = s => String(s).replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
const colorAt = i => CFG.PALETTE[i % CFG.PALETTE.length];

function toNum(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  const s = String(v).trim().replace(/,/g, '');
  if (!/^-?\d+(\.\d+)?$/.test(s)) return null;
  const n = parseFloat(s);
  return Number.isFinite(n) ? n : null;
}

function fmtCell(v) {
  if (v === null || v === undefined) return '';
  if (typeof v === 'number') {
    return Number.isInteger(v) ? v.toLocaleString('en-US')
                               : v.toLocaleString('en-US', { maximumFractionDigits: 2 });
  }
  const s = String(v);
  if (/^\d{4}-\d{2}-\d{2}T/.test(s)) return s.slice(0, 10);
  return mdSafe(s);
}

// ---------- ۱. جدول Markdown ----------
function markdownTable(rows, cols) {
  const shown = rows.slice(0, CFG.MAX_TABLE);
  let md = '| ' + cols.map(mdSafe).join(' | ') + ' |\n';
  md += '| ' + cols.map(() => '---').join(' | ') + ' |\n';
  for (const r of shown) md += '| ' + cols.map(c => fmtCell(r[c])).join(' | ') + ' |\n';
  if (rows.length >= CFG.ROW_CAP) {
    md += `\n_نتیجه به ${CFG.ROW_CAP} ردیف محدود شده و ممکن است ردیف‌های بیشتری وجود داشته باشد؛ برای نتیجه کامل سوال را محدودتر بپرسید (مثلاً «۲۰ مورد اول» یا یک بازه زمانی)._\n`;
  } else if (rows.length > shown.length) {
    md += `\n_${rows.length} ردیف یافت شد، ${shown.length} ردیف اول نمایش داده شده._\n`;
  }
  return md;
}

// ---------- ۲. کدام ستون عدد (اندازه) و کدام برچسب است ----------
function chartColumns(rows, cols) {
  const numericCols = cols.filter(c => rows.some(r => toNum(r[c]) !== null)
                                    && rows.every(r => r[c] === null || toNum(r[c]) !== null));
  const valueCol = numericCols.length ? numericCols[numericCols.length - 1] : null;
  const labelCols = cols.filter(c => c !== valueCol).slice(0, 3);
  const isTemporal = labelCols.some(c =>
    /date|month|year|day|quarter|week|period|تاریخ|ماه|سال|روز|فصل|هفته|دوره/i.test(c));
  return { valueCol, labelCols, isTemporal };
}

// ---------- ۳. نوع نمودار: اول آنچه کاربر خواسته، بعد بر اساس شکل داده ----------
function chartType(question, rowCount, isTemporal) {
  if (/دایره|پای|کیک|سهم|\bpie\b/i.test(question))               return 'pie';
  if (/خطی|روند|تغییرات|\btrend\b|\bline\b/i.test(question)) return 'line';
  if (/میله|ستون|\bbar\b|\bcolumn\b/i.test(question))        return 'bar';
  if (/نمودار|چارت|\bchart\b|\bgraph\b|رسم/i.test(question) || CFG.AUTO_CHART) {
    if (isTemporal)        return 'line';
    if (rowCount <= 6)     return 'pie';
    return 'bar';
  }
  return null;
}

const clean = v => String(v ?? '').replace(/[\[\],;]/g, ' ').replace(/\s+/g, ' ').trim();
const safeTitle = v => clean(String(v ?? '').replace(/[:]/g, ' ')).slice(0, 70);

// [{ label, value }] - یک نقطه برای هر ردیف؛ [] وقتی برچسب تکراری است (هر ردیف یک نقطه مستقل نیست)
function chartPoints(rows, { valueCol, labelCols }, cap) {
  const data = rows.map(r => ({
    // برچسب کامل نگه داشته می‌شود؛ Chart.js خودش فضای لازم را برای آن رزرو می‌کند
    label: labelCols.map(c => clean(fmtCell(r[c]))).filter(Boolean).join(' ').slice(0, 40),
    value: Math.round((toNum(r[valueCol]) ?? 0) * 100) / 100
  })).filter(d => d.label).slice(0, cap);   // ترتیب از ORDER BY کوئری می‌آید؛ دوباره مرتب نمی‌کنیم
  return new Set(data.map(d => d.label)).size === data.length ? data : [];
}

// ---------- ۴. تنظیمات Chart.js برای هر نوع ----------
// { config, width, height } یا null (مثلاً نمودار دایره‌ای با کمتر از دو مقدار مثبت)
function pieChart(data, title) {
  const positive = data.filter(d => d.value > 0);
  if (positive.length < 2) return null;
  return {
    config: {
      type: 'pie',
      data: {
        labels: positive.map(d => d.label),
        datasets: [{ data: positive.map(d => d.value), backgroundColor: positive.map((_, i) => colorAt(i)) }]
      },
      options: {
        plugins: {
          title: { display: true, text: title, font: { size: 18 } },
          legend: { position: 'right', labels: { font: { size: 13 } } }
        }
      }
    },
    width: 640, height: 480
  };
}

function lineChart(data, title, valueCol) {
  const labels = data.map(d => d.label);
  return {
    config: {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: safeTitle(valueCol),
          data: data.map(d => d.value),
          borderColor: colorAt(0),
          backgroundColor: colorAt(0),
          pointBackgroundColor: labels.map((_, i) => colorAt(i)),
          pointRadius: 4,
          tension: 0.25,
          fill: false
        }]
      },
      options: {
        plugins: {
          title: { display: true, text: title, font: { size: 18 } },
          legend: { display: false }
        },
        scales: {
          x: { ticks: { font: { size: 13 } } },
          y: { title: { display: true, text: safeTitle(valueCol) }, beginAtZero: true }
        }
      }
    },
    width: Math.min(1200, Math.max(650, data.length * 70)),
    height: 460
  };
}

function barChart(data, title, valueCol) {
  const labels = data.map(d => d.label);
  // میله افقی وقتی برچسب‌ها طولانی یا تعدادشان زیاد است خواناتر است
  const avgLabelLen = labels.reduce((s, l) => s + l.length, 0) / labels.length;
  const horizontal = data.length > 8 || avgLabelLen > 14;
  return {
    config: {
      type: 'bar',
      data: {
        labels,
        datasets: [{
          label: safeTitle(valueCol),
          data: data.map(d => d.value),
          backgroundColor: labels.map((_, i) => colorAt(i)),
          borderRadius: 4
        }]
      },
      options: {
        indexAxis: horizontal ? 'y' : 'x',
        plugins: {
          title: { display: true, text: title, font: { size: 18 } },
          legend: { display: false }
        },
        scales: horizontal
          ? { x: { title: { display: true, text: safeTitle(valueCol) }, beginAtZero: true },
              y: { ticks: { autoSkip: false, font: { size: 13 } } } }
          : { x: { ticks: { font: { size: 12 } } },
              y: { title: { display: true, text: safeTitle(valueCol) }, beginAtZero: true } }
      }
    },
    width: horizontal ? 760 : Math.min(1300, Math.max(650, data.length * 80)),
    height: horizontal ? Math.min(1200, Math.max(420, data.length * 38 + 110)) : 460   // فضای کافی برای هر ردیف برچسب
  };
}

const CHART_BUILDERS = { pie: pieChart, line: lineChart, bar: barChart };

// ---------- ۵. آدرس تصویر نمودار ----------
// URLSearchParams در sandbox نود Code موجود نیست؛ کوئری‌استرینگ را دستی می‌سازیم
function chartUrl({ config, width, height }) {
  const params = {
    c: JSON.stringify(config),
    w: String(width),
    h: String(height),
    backgroundColor: 'white',
    version: '4',
    devicePixelRatio: '2'
  };
  const qs = Object.entries(params).map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');
  return `${CFG.CHART_BASE_URL}/chart?${qs}`;
}

// { markdown, note } - note وقتی نمودار فقط بخشی از ردیف‌ها را نشان می‌دهد
function chartFor(question, rows, cols) {
  const columns = chartColumns(rows, cols);
  const type = chartType(question, rows.length, columns.isTemporal);
  const cap = Math.min(CFG.MAX_CHART, CFG.CHART_LIMITS[type] || CFG.MAX_CHART);
  const note = rows.length > cap && type
    ? `\n_نمودار برای خوانایی بیشتر به ${cap} ردیف اول محدود شده است (از مجموع ${rows.length} ردیف)._\n` : '';
  if (!type || !columns.valueCol || !columns.labelCols.length || rows.length < 2) return { markdown: '', note };
  const data = chartPoints(rows, columns, cap);
  if (data.length < 2) return { markdown: '', note };
  const title = safeTitle(question) || safeTitle(`${columns.valueCol} بر اساس ${columns.labelCols.join(' و ')}`);
  const chart = CHART_BUILDERS[type](data, title, columns.valueCol);
  return { markdown: chart ? `\n![${title}](${chartUrl(chart)})\n` : '', note };
}

// ---------- ۶. یادداشت‌های Obsidian پشت جواب ----------
// هر جدول یک یادداشت در Obsidian/Catalog دارد و هر معیار در یادداشت حوزه‌اش است؛ کاربر می‌بیند جواب از کجا آمد
function notesFooter(selectedEntities, metrics) {
  const parts = [...selectedEntities, ...metrics.map(m => `معیار «${m}»`)];
  return parts.length ? `\n\n📎 یادداشت‌های Obsidian: ${parts.join(' · ')}` : '';
}

// ---------- اجرا ----------
function formatAnswer({ rows, question, sec, can, selectedEntities, metrics = [] }) {
  const thinking = (sec.thinking || '').trim();
  const thinkBlock = thinking ? `<think>\n${thinking}\n</think>\n\n` : '';
  let answer;
  if (rows.length === 0) {
    answer = thinkBlock + 'نتیجه‌ای یافت نشد.';
  } else {
    const cols = Object.keys(rows[0]);
    const chart = chartFor(question, rows, cols);
    answer = thinkBlock + markdownTable(rows, cols) + chart.note + chart.markdown;
  }
  answer += notesFooter(selectedEntities, metrics);
  return can.evalMode
    ? { answer, rows, sql: sec.sql || '', modelSql: sec.modelSql || '', understood: sec.understood || '',
        plan: sec.plan || '', retried: sec.attempt === 2, selectedEntities }
    : { answer };
}

return [{ json: formatAnswer(readN8nInputs()) }];

// ===== Audit Row: یک ردیف برای جدول NLSQL_AuditLog پس از هر پاسخ موفق =====
// ورودی:  ردیف‌های نتیجه کوئری؛ کاربر (AuthCheck)، سوال (Webhook) و SQL (Security)
// خروجی:  یک ردیف با ستون‌های NLSQL_AuditLog
// نود بعدی (Write Audit Log) این ردیف را در SQL Server می‌نویسد؛ تا وقتی جدول و login مخصوصش ساخته
// نشده (sql/NLSQL_AuditLog.sql) آن نود بی‌خطر شکست می‌خورد و پاسخ کاربر تغییری نمی‌کند.

// ---------- ۱. آداپتر n8n: تنها جایی که $input و $('...') خوانده می‌شود ----------
function readN8nInputs() {
  return {
    rowCount: $input.all().length,
    username: $('AuthCheck').first().json.username,
    question: $('Webhook').first().json.body.question,
    sec: $('Security').first().json,
  };
}

// ---------- ۲. منطق ----------
function auditRow({ rowCount, username, question, sec }) {
  return {
    username: username || 'unknown',
    question: question || '',
    generated_sql: sec.sql || '',
    understood_query: sec.understood || '',
    thinking: sec.thinking || '',
    attempt: sec.attempt || 1,
    status: 'SUCCESS',
    row_count: rowCount,
  };
}

// ---------- ۳. اجرا ----------
return [{ json: auditRow(readN8nInputs()) }];

// ===== لایه امنیتی: استخراج SQL از پاسخ مدل، بررسی آن و ساخت کوئری نهایی =====
//
// ساختار (SOLID):
//   ۰. سیاست (POLICY)          - فهرست‌ها و عددهای امنیتی به‌صورت داده، جدا از منطق
//   ۱. آداپتر n8n (ورودی)      - تنها جایی که $input و $('...') خوانده می‌شود (DIP)
//   ۲. مراحل خالص              - هر مرحله یک مسئولیت (SRP): خواندن پاسخ، جدا کردن SQL،
//                                بررسی فقط-خواندنی، سقف ردیف، بررسی ارجاع‌ها، ساخت CTE
//   ۳. ترکیب (secure)          - ترتیب مراحل
//   ۴. آداپتر n8n (خروجی)      - قرارداد خروجی که execute query، Retry once? (attempt)،
//                                Build Fix Prompt و نودهای نتیجه/لاگ می‌خوانند
// هر مرحله با throw یک Error که با ⛔ شروع می‌شود کوئری را رد می‌کند (خروجی خطا → ErrorFormat).

// ==================== ۰. سیاست ====================
const POLICY = {
  ROW_CAP: 200,                // سقف ردیف اجباری برای هر کوئری
  RESPONSE_KEYS: ['result', 'response', 'answer', 'text', 'output', 'message', 'content'],
  THINK_KEYS:    ['thinking', 'reasoning', 'reasoning_content', 'thoughts'],
  BLOCKED: [
    /\binsert\b/i, /\bupdate\b/i, /\bdelete\b/i, /\bdrop\b/i,
    /\btruncate\b/i, /\balter\b/i, /\bcreate\b/i, /\bmerge\b/i,
    /\bexec\b/i, /\bexecute\b/i, /\bgrant\b/i, /\brevoke\b/i,
    /\bbackup\b/i, /\brestore\b/i, /\bshutdown\b/i, /\bwaitfor\b/i,
    /\binto\b/i, /\bxp_\w+/i, /\bsp_\w+/i, /openrowset/i, /opendatasource/i,
    // اصلاح امنیتی ۴: DBCC می‌تواند دستورات مدیریتی/DoS اجرا کند؛
    // APPLY می‌تواند توابع دلخواه (خارج از کاتالوگ) را صدا بزند - هر دو مسدود می‌شوند
    /\bdbcc\b/i, /\bapply\b/i, /\bopenxml\b/i
  ],
  FORBIDDEN_TOKENS: [';', '--', '/*']
};

// ==================== ۱. آداپتر n8n: ورودی ====================
function readN8nInputs() {
  // شماره تلاش: آیا این اجرای دوباره بعد از خطای SQL است؟ همان الگوی موجود در این ورک‌فلو
  // (تشخیص با وجود/عدم وجود یک نود که فقط در مسیر retry اجرا می‌شود) - Build Fix Prompt
  // فقط بعد از شکست اجرای کوئری اول اجرا می‌شود.
  let attempt = 1;
  try { $('Build Fix Prompt').first(); attempt = 2; } catch (e) { attempt = 1; }
  return {
    res: $input.first().json,
    // entityDefs فقط وقتی لازم است که پاسخ مدل تا مرحله بررسی ارجاع‌ها برسد
    getEntityDefs: () => $('BuildPrompt').first().json.entityDefs || {},
    attempt
  };
}

// ==================== ۲. مراحل خالص ====================
const reject = msg => { throw new Error(msg); };

// ---------- ۲-۱. استخراج متن پاسخ از API ----------
function extractResponseText(res) {
  let raw = '';
  if (typeof res === 'string') {
    raw = res;
  } else {
    for (const k of POLICY.RESPONSE_KEYS) {
      if (typeof res[k] === 'string' && res[k].trim()) { raw = res[k]; break; }
    }
    if (!raw) {
      const s = Object.values(res).find(v => typeof v === 'string' && v.trim().length > 5);
      if (s) raw = s;
    }
  }
  if (!raw) reject('⛔ ساختار پاسخ API شناخته نشد: ' + JSON.stringify(res).slice(0, 300));
  return raw;
}

// ---------- ۲-۲. جدا کردن reasoning/thinking و پاکت UNDERSTOOD: ... / PLAN: ... / SQL: ... ----------
// thinking برای نمایش در OpenWebUI نگه داشته می‌شود؛ PLAN (برنامه کوئری که مدل پیش از SQL می‌نویسد)
// هم جداگانه برگردانده می‌شود و هم جزء thinking نمایش داده می‌شود. متن PLAN هرگز به‌عنوان SQL خوانده
// نمی‌شود، حتی اگر مدل برچسب SQL: را جا بیندازد (کلمه with یا select در PLAN).
function parseEnvelope(res, text) {
  let raw = text;
  let thinking = '';
  if (typeof res === 'object' && res) {
    for (const k of POLICY.THINK_KEYS) {
      if (typeof res[k] === 'string' && res[k].trim()) { thinking += res[k].trim() + '\n'; break; }
    }
  }
  const thinkTag = raw.match(/<think>([\s\S]*?)<\/think>/i);
  if (thinkTag) {
    thinking += thinkTag[1].trim();
    raw = raw.replace(thinkTag[0], '').trim();
  }

  let understood = '';
  const understoodMatch = raw.match(/UNDERSTOOD:\s*(.+)/i);
  if (understoodMatch) understood = understoodMatch[1].split(/\b(?:PLAN|SQL)\s*:/i)[0].trim();

  // برچسب SQL: که سر خط آمده (با ** یا # احتمالی مارک‌داون)؛ نه کلمه SQL داخل متن PLAN. اگر PLAN
  // نیست، برچسب وسط خط هم قبول است («UNDERSTOOD: ... SQL: SELECT ...» در یک خط، شکل قدیمی پاسخ).
  const hasPlan = /(^|\n)[ \t>*#]*PLAN[ \t*]*:/i.test(raw);
  const sqlLabel = /(^|\n)[ \t>*#]*SQL[ \t*]*:[ \t*]*/i.exec(raw) || (hasPlan ? null : /()\bSQL\s*:\s*/i.exec(raw));
  const sqlMarker = sqlLabel ? sqlLabel.index + sqlLabel[1].length : -1;
  let plan = '';
  const before = sqlMarker !== -1 ? raw.slice(0, sqlMarker) : raw;
  const planMatch = before.match(/(^|\n)[ \t>*#]*PLAN[ \t*]*:[ \t*]*([\s\S]*)$/i);
  if (planMatch) plan = planMatch[2].trim();

  if (sqlMarker !== -1) {
    const leftover = before.replace(/UNDERSTOOD:.*$/im, '').trim();
    if (leftover) thinking = (thinking ? thinking + '\n' : '') + leftover;
    raw = raw.slice(sqlMarker + sqlLabel[0].length - sqlLabel[1].length).trim();
  } else {
    // بدون برچسب SQL: متن UNDERSTOOD و PLAN کنار گذاشته می‌شود تا extractSql فقط بقیه را ببیند
    if (planMatch) {
      // PLAN تا اولین خطی که با SELECT یا WITH شروع می‌شود ادامه دارد
      const planStart = before.length - planMatch[0].length + planMatch[1].length;
      const rest = raw.slice(planStart);
      const sqlLine = rest.search(/\n\s*(select|with)\b/i);
      plan = (sqlLine === -1 ? rest : rest.slice(0, sqlLine)).replace(/^[ \t>*#]*PLAN[ \t*]*:[ \t*]*/i, '').trim();
      thinking = (thinking ? thinking + '\n' : '') + 'PLAN:\n' + plan;
      raw = raw.slice(0, planStart) + (sqlLine === -1 ? '' : rest.slice(sqlLine));
    }
    if (understoodMatch) raw = raw.replace(understoodMatch[0], '');
    raw = raw.trim();
  }
  return { body: raw, understood, thinking, plan };
}

// ---------- ۲-۳. جدا کردن SQL از متن پرحرف مدل ----------
const SQLKW = /^\s*(select|from|where|group|order|having|join|inner|left|right|full|cross|outer|on|and|or|union|with|as|top|case|when|then|else|end|\)|,)/i;

// یک خط فقط وقتی «توضیح فارسی مدل» است که بعد از حذف شناسه‌های [...] و "..." و رشته‌های '...'
// هنوز حرف فارسی داشته باشد. قبلاً هر خط فارسی‌دار (مگر با کلمه کلیدی SQL یا ' شروع می‌شد)
// حذف می‌شد؛ پس کوئری چندخطی که ستون‌های فارسی‌نام PaymentReceiveInfo (۳۷ ستون) یا alias
// فارسی ([جمع مبلغ]) را در خط‌های جدا می‌آورد، بی‌صدا ستون از دست می‌داد یا خراب می‌شد.
const PERSIAN = /[؀-ۿ]/;
const withoutQuotedParts = l => l
  .replace(/\[[^\]]*\]/g, '')
  .replace(/"[^"]*"/g, '')
  .replace(/'(?:[^']|'')*'/g, '');
const isPersianProse = l => PERSIAN.test(withoutQuotedParts(l));

function extractSql(body) {
  let sql = '';
  const fence = body.match(/```sql\s*([\s\S]*?)```/i) || body.match(/```\s*([\s\S]*?)```/);
  if (fence) {
    sql = fence[1].trim();
  } else {
    const m = body.match(/\b(select|with)\b[\s\S]*/i);
    sql = m ? m[0].trim() : body.trim();
    sql = sql.split(/\n\s*\n/)[0].trim();
  }
  sql = sql.split('\n')
           .filter(l => !isPersianProse(l) || SQLKW.test(l))
           .join('\n').trim();
  sql = sql.replace(/;+\s*$/, '').trim();
  if (!sql) reject('⛔ مدل نتوانست کوئری تولید کند. لطفاً سوال را واضح‌تر بپرسید.');
  return sql;
}

// ---------- ۲-۴. پاسخ «پشتیبانی نمی‌شود» مدل ----------
// BuildPrompt از مدل می‌خواهد وقتی داده لازم در schema نیست دقیقاً
// SELECT 'NOT_SUPPORTED' AS Status, '<reason>' AS Reason برگرداند. این کوئری به هیچ
// موجودیتی ارجاع ندارد و قبلاً با پیام گمراه‌کننده «کوئری به هیچ موجودیت معتبری ارجاع
// ندارد» رد می‌شد و دلیل مدل گم می‌شد. اینجا صریحاً همان را به کاربر می‌گوییم.
function rejectIfNotSupported(sql, understood) {
  if (!/^\s*select\s+(?:top\s+\d+\s+)?'NOT_SUPPORTED'/i.test(sql)) return;
  const reasonMatch = sql.match(/'NOT_SUPPORTED'\s+as\s+\[?status\]?\s*,\s*'((?:[^']|'')*)'/i);
  const reason = reasonMatch ? reasonMatch[1].replace(/''/g, "'").trim() : '';
  reject('⛔ این سوال با داده‌هایی که به آن دسترسی دارید قابل پاسخ نیست.'
    + (reason ? '\n\n' + reason : (understood ? '\n\n' + understood : '')));
}

// ---------- ۲-۵. تور ایمنی: LIMIT n → TOP n ----------
function limitToTop(sql) {
  const lim = sql.match(/\blimit\s+(\d+)\s*;?\s*$/i);
  if (!lim) return sql;
  let out = sql.replace(/\blimit\s+\d+\s*;?\s*$/i, '').trim();
  if (!/^\s*select\s+top\b/i.test(out)) out = out.replace(/^\s*select\b/i, `SELECT TOP ${lim[1]}`);
  return out;
}

// ---------- ۲-۶. فقط SELECT و بدون دستور/کاراکتر غیرمجاز ----------
// اصلاح امنیتی ۲: JOIN با کاما (implicit join) از بررسی ارجاع‌ها فرار می‌کند چون آن بررسی
// فقط دنبال FROM/JOIN می‌گردد، نه کاما. hasImplicitCommaJoin هر FROM را تا اولین بند مرزی
// (در همان عمق پرانتز) اسکن می‌کند و اگر کاما دید، کوئری رد می‌شود.
// نام‌های [..] و ".." و رشته‌های '..' خالی می‌شوند (طولشان مهم نیست): کلمه FROM داخل نام ستونی مثل [From] یا داخل
// یک رشته نباید بررسی شود و ستون [From] را به‌اشتباه رد کند.
const blankNames = s => s.replace(/\[[^\]]*\]/g, '[x]').replace(/"[^"]*"/g, '"x"').replace(/'(?:[^']|'')*'/g, "''");

function hasImplicitCommaJoin(sql) {
  const s = blankNames(sql);
  const boundaryRe = /^\s*(where|group\s+by|order\s+by|having|union|except|intersect|for\b)\b/i;
  const fromRe = /\bfrom\b/gi;
  let m;
  while ((m = fromRe.exec(s)) !== null) {
    let i = m.index + m[0].length;
    let depth = 0, quote = null;
    while (i < s.length) {
      const ch = s[i];
      if (quote) { if (ch === quote) quote = null; i++; continue; }
      if (ch === "'" || ch === '"') { quote = ch; i++; continue; }
      if (ch === '[') { const e = s.indexOf(']', i); i = (e === -1 ? s.length : e + 1); continue; }
      if (ch === '(') { depth++; i++; continue; }
      if (ch === ')') { if (depth === 0) break; depth--; i++; continue; }
      if (depth === 0) {
        if (ch === ',') return true;
        // only at the start of a word: the alias «somewhere» or «t_for» is not WHERE / FOR (that let
        // «FROM [Fact_Sales] somewhere, Secret» through)
        if ((i === 0 || !/\w/.test(s[i - 1])) && boundaryRe.test(s.slice(i))) break;
      }
      i++;
    }
  }
  return false;
}

// اصلاح امنیتی ۶: بعد از FROM/JOIN فقط نام جدول یا یک زیرکوئری مجاز است. «FROM ([Secret] s CROSS JOIN ...)»،
// «FROM #temp»، «FROM @t» و «FROM ::fn» از بررسی ارجاع‌ها (که فقط نام بعد از FROM/JOIN را می‌بیند) فرار می‌کردند.
// نام‌ها و رشته‌ها اول خالی می‌شوند تا ستونی به نام [From] یا متن N'from' اشتباه رد نشود.
function hasUncheckedTableSource(s) {
  const t = blankNames(s);
  const re = /\b(?:from|join)\b\s*((?:\(\s*)*)/gi;
  let m;
  while ((m = re.exec(t)) !== null) {
    const rest = t.slice(m.index + m[0].length);
    if (m[1] ? !/^(?:select|with|values)\b/i.test(rest) : !/^(?:\[|"|[A-Za-z_])/.test(rest)) return true;
  }
  return false;
}

function assertReadOnly(sql) {
  if (!/^\s*(select|with)\b/i.test(sql)) reject('⛔ عملیات مجاز نیست: فقط SELECT.');
  for (const p of POLICY.BLOCKED) {
    if (p.test(sql)) reject('⛔ عملیات مجاز نیست: دستور غیرمجاز.');
  }
  if (POLICY.FORBIDDEN_TOKENS.some(t => sql.includes(t))) reject('⛔ عملیات مجاز نیست: کاراکتر غیرمجاز.');
  if (hasImplicitCommaJoin(sql)) reject('⛔ فقط سینتکس JOIN صریح مجاز است (نه کاما در FROM).');
  if (hasUncheckedTableSource(sql)) reject('⛔ بعد از FROM یا JOIN فقط نام جدول یا یک زیرکوئری (SELECT ...) مجاز است.');
}

// ---------- ۲-۷. سقف ردیف اجباری ----------
function injectTop(s, n) {
  if (/^\s*select\s+top\b/i.test(s)) return s;
  if (/^\s*select\b/i.test(s)) return s.replace(/^\s*select\b/i, `SELECT TOP ${n}`);
  let depth = 0, quote = null;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (quote) { if (ch === quote) quote = null; continue; }
    if (ch === "'" || ch === '"') { quote = ch; continue; }
    if (ch === '(') depth++;
    else if (ch === ')') depth--;
    else if (depth === 0 && (ch === 's' || ch === 'S') && /^select\b/i.test(s.slice(i))) {
      const before = i === 0 ? ' ' : s[i - 1];
      if (/[A-Za-z0-9_\]]/.test(before)) continue;
      if (/^select\s+top\b/i.test(s.slice(i))) return s;
      return s.slice(0, i) + `SELECT TOP ${n}` + s.slice(i + 6);
    }
  }
  return s;
}

// ---------- ۲-۸. اعتبارسنجی: فقط موجودیت‌های انتخاب‌شده ----------
// اصلاح امنیتی ۳: پشتیبانی از شناسه‌های داخل گیومه "..." علاوه بر [...]
const IDENT = '(?:\\[[^\\]]+\\]|"[^"]+"|[A-Za-z0-9_]+)';
const stripQuotes = t => t.replace(/^\[|\]$/g, '').replace(/^"|"$/g, '');

// نام CTEهایی که خود مدل در WITH تعریف کرده (کوچک‌شده)
function modelCteNames(sql) {
  const names = new Set();
  const cteRe = new RegExp(`(?:\\bwith\\b|,)\\s*(${IDENT})\\s+as\\s*\\(`, 'gi');
  let m;
  while ((m = cteRe.exec(sql)) !== null) names.add(stripQuotes(m[1]).toLowerCase());
  return names;
}

// نام‌های (کوچک‌شده) موجودیت‌های کاتالوگ که کوئری از آن‌ها می‌خواند؛ هر ارجاع دیگری رد می‌شود.
//
// اصلاح امنیتی ۵ - نام‌های چندبخشی ([schema].[table] یا [db].[schema].[table]):
// کوئری باید فقط از CTE موجودیت‌ها بخواند. ۱۹ نام موجودیت (مثل Fact_Invoice که منبعش
// [PRC].[Fact_Invoice_2] است) با یک جدول فیزیکی قدیمی هم‌نام در همان schema یکی‌اند؛ قبلاً فقط
// بخش آخر نام بررسی می‌شد، پس FROM [PRC].[Fact_Invoice] جدول قدیمی را مستقیم (با همه ستون‌ها و
// داده متفاوت) می‌خواند. بدتر: اگر بخش آخر با نام یک CTE خود مدل یکی بود اصلاً بررسی نمی‌شد، پس
// WITH [Fact_Sales] AS (...) SELECT * FROM [dbo].[Fact_Sales] هر جدولی را بدون مجوز می‌خواند.
// حالا نام چندبخشی هیچ‌وقت CTE مدل حساب نمی‌شود (CTE همیشه یک‌بخشی است)؛ اگر بخش آخرش
// موجودیت مجاز باشد به CTE همان موجودیت بازنویسی می‌شود، وگرنه رد می‌شود.
function resolveReferences(sql, entityDefs, log) {
  const allowedNames = new Set(Object.keys(entityDefs).map(n => n.toLowerCase()));
  const cteNames = modelCteNames(sql);

  // اصلاح امنیتی ۱: اگر مدل نام یک CTE را برابر با یک موجودیت واقعی کاتالوگ تعریف کند،
  // می‌تواند آن موجودیت را با منبع دلخواه خودش جایگزین (shadow) کند و کل کنترل دسترسی
  // را دور بزند. به‌جای رد شدن بی‌سروصدا از این حالت، صراحتاً آن را مسدود می‌کنیم.
  for (const cn of cteNames) {
    if (allowedNames.has(cn)) reject('⛔ نام‌گذاری غیرمجاز: نام CTE با یک موجودیت کاتالوگ تداخل دارد.');
  }

  const referenced = new Set();
  const qualified  = new Map(); // متن نام چندبخشی ← [نام موجودیت]
  // «JOIN[dbo].[Secret]» و «FROM"Secret"» (بدون فاصله) هم ارجاع‌اند
  const refRe  = new RegExp(`\\b(?:from|join)(?:\\s+|(?=[\\["]))(${IDENT}(?:\\.${IDENT}){0,2})`, 'gi');
  const partRe = new RegExp(IDENT, 'g'); // نقطه داخل [...] جداکننده نیست
  let m;
  while ((m = refRe.exec(sql)) !== null) {
    const parts = m[1].match(partRe);
    const last  = stripQuotes(parts[parts.length - 1]);
    const nm    = last.toLowerCase();
    if (parts.length === 1 && cteNames.has(nm)) continue; // CTE واقعی و بی‌ضرر خود مدل
    if (!allowedNames.has(nm)) reject('⛔ اجرای این دستور خارج از حیطه دسترسی شماست.');
    if (parts.length > 1) qualified.set(m[1], `[${last}]`);
    referenced.add(nm);
  }
  if (referenced.size === 0) reject('⛔ کوئری تولیدشده به هیچ موجودیت معتبری ارجاع ندارد.');

  // همه رخدادهای نام چندبخشی (در FROM/JOIN و در پیشوند ستون‌ها مثل [PRC].[Fact_Invoice].[NetPrice])
  // به نام CTE تبدیل می‌شوند؛ طولانی‌ترها اول تا یک نام سه‌بخشی نیمه‌کاره جایگزین نشود.
  // مرز شناسه رعایت می‌شود تا dbo.Fact_Employee بخشی از dbo.Fact_EmployeeX را عوض نکند.
  const escapeRe = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  let out = sql;
  for (const [text, repl] of [...qualified].sort((a, b) => b[0].length - a[0].length)) {
    const pattern = (/^\w/.test(text) ? '(?<![\\w.\\]])' : '') + escapeRe(text) + (/\w$/.test(text) ? '(?!\\w)' : '');
    out = out.replace(new RegExp(pattern, 'g'), repl);
    log('QUALIFIED NAME REWRITTEN | ' + text + ' -> ' + repl);
  }
  return { sql: out, referenced };
}

// ---------- ۲-۹. ساخت CTE برای موجودیت‌های ارجاع‌شده ----------
// هر نوع موجودیت (kind) سازنده خودش را دارد؛ نوع جدید = یک سازنده جدید در این نگاشت،
// بدون تغییر بقیه کد. نوع ناشناخته صریحاً رد می‌شود و بی‌صدا «جدول» فرض نمی‌شود.
const CTE_BUILDERS = {
  table: (d, name) => {
    if (!d.source) reject(`⛔ منبع موجودیت [${name}] در کاتالوگ تعریف نشده است.`);
    const cols = (d.columns || []).map(c => c.alias ? `[${c.name}] AS [${c.alias}]` : `[${c.name}]`);
    return `[${d.name}] AS (SELECT ${cols.join(', ')} FROM ${d.source})`;
  },
  virtual: (d, name) => {
    if (!d.sql) reject(`⛔ تعریف موجودیت [${name}] در کاتالوگ ناقص است.`);
    return `[${d.name}] AS (\n${d.sql}\n)`;
  }
};

function buildEntityCtes(entityDefs, referenced) {
  return Object.keys(entityDefs)
    .filter(name => referenced.has(name.toLowerCase()))
    .map(name => {
      const d = entityDefs[name];
      const builder = CTE_BUILDERS[d.kind || 'table'];
      if (!builder) reject(`⛔ نوع موجودیت [${name}] («${d.kind}») پشتیبانی نمی‌شود.`);
      return builder(d, name);
    });
}

// ---------- ۲-۱۰. ادغام CTEهای کاتالوگ با WITH خود مدل ----------
function mergeWithModelSql(cteParts, sql) {
  const prefix = 'WITH ' + cteParts.join(',\n');
  return /^\s*with\b/i.test(sql)
    ? prefix + sql.replace(/^\s*with\b/i, ',\n')
    : prefix + '\n' + sql;
}

// ==================== ۳. ترکیب ====================
function secure(input, log) {
  const envelope = parseEnvelope(input.res, extractResponseText(input.res));
  let sql = extractSql(envelope.body);
  rejectIfNotSupported(sql, envelope.understood);
  sql = limitToTop(sql);
  assertReadOnly(sql);
  sql = injectTop(sql, POLICY.ROW_CAP);

  const entityDefs = input.getEntityDefs();
  const resolved = resolveReferences(sql, entityDefs, log);
  const finalSql = mergeWithModelSql(buildEntityCtes(entityDefs, resolved.referenced), resolved.sql);

  return {
    sql: finalSql,
    modelSql: resolved.sql,
    entities: [...resolved.referenced],
    understood: envelope.understood,
    plan: envelope.plan,
    thinking: envelope.thinking,
    attempt: input.attempt
  };
}

// ==================== ۴. آداپتر n8n: خروجی ====================
return [{ json: secure(readN8nInputs(), msg => console.log(msg)) }];

// ===== BuildPrompt: نوشتن متن prompt برای Qwen از روی طرحی که Find Tables ساخته =====
//
// ورودی:  خروجی نود Find Tables = جواب catalog-service (POST /tables): جدول‌ها به ترتیب اهمیت، روابط (joins)،
//         راهنماها، مثال‌ها، مقدارها، معیارها - یا { refusal: '⛔ ...' } وقتی کاربر به جدول مناسبی دسترسی ندارد
//         (همان پیام به ErrorFormat می‌رود)
// خروجی:  body.string2 = متن prompt برای «request to LLM»؛ entityDefs برای Security؛
//         selectedEntities و retrieval برای Format Answer، ErrorFormat و یادداشت Obsidian
//
// مراحل (تابع buildPrompt در انتهای فایل):
//   ۱. جا دادن جدول‌ها   packPrompt     از بالای فهرست تا سقف MAX_PROMPT_CHARS؛ جدول اول همیشه
//   ۲. پاک‌سازی           packPrompt     مثال/مقدار/معیاری که جدولش جا نماند حذف می‌شود
//   ۳. متن نهایی          renderPrompt   قوانین + امروز + راهنماها + معیارها + مقدارها + مثال‌ها + جدول‌ها + سوال
//
// برای تغییر متن یا قوانین prompt فقط renderPrompt را عوض کنید؛ این نود به کاتالوگ دسترسی ندارد.

// ==================== تنظیمات ====================
const CFG = {
  MAX_PROMPT_CHARS:     24000   // بودجه اندازه کل prompt (قوانین + راهنماها + مثال‌ها + مقدارها + معیارها + DDL + روابط + سوال).
                                // برای Qwen 32B (پنجره ۳۲ هزار توکنی): DDL انگلیسی با توضیح فارسی حدود ۳ کاراکتر در هر
                                // توکن است، پس ۲۴۰۰۰ کاراکتر ≈ ۸ هزار توکن و جای کافی برای PLAN و SQL می‌ماند.
                                // جدولی که به prompt نرسد با هیچ مدلی جبران نمی‌شود. obsidian/How-to.md (LLM settings)
};

// ==================== ورودی n8n ====================
function readN8nInputs() {
  return { plan: $input.first().json, now: new Date() };
}

// ==================== تکه‌های متن prompt ====================
// ---------- تاریخ امروز (برای «امسال»، «ماه گذشته»، «سال ۱۴۰۳») ----------
// مدل تاریخ امروز را نمی‌داند و سال شمسی را با میلادی قاطی می‌کند. تاریخ به وقت تهران.
function todayLine(now) {
  let greg = now.toISOString().slice(0, 10);
  let persian = '';
  try {
    greg = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Tehran', year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
    const parts = new Intl.DateTimeFormat('en-US-u-ca-persian', { timeZone: 'Asia/Tehran', year: 'numeric', month: '2-digit', day: '2-digit' })
      .formatToParts(now).reduce((acc, x) => Object.assign(acc, { [x.type]: x.value }), {});
    if (/^\d{4}$/.test(parts.year)) persian = `${parts.year}/${parts.month}/${parts.day}`;
  } catch (e) { /* Intl بدون تقویم فارسی: فقط تاریخ میلادی */ }
  return `- TODAY is ${greg}${persian ? ` (Persian date ${persian})` : ''}. Resolve relative periods (امسال، ماه گذشته، this year, last month) from it.\n`
    + '- A year like 1403 / ۱۴۰۳ is a Persian (شمسی) year, 2024 is Gregorian (میلادی). Filter Persian years and months with the Persian columns of [Dim_Date] (or a Persian date column of the table itself); use YEAR()/MONTH() only for Gregorian periods.\n';
}

const sqlLit = v => "N'" + String(v).replace(/'/g, "''") + "'";
function valueLine(l) {
  const ref = `[${l.entity}].[${l.column}]`;
  const key = l.key && l.keyValue != null ? `  (key: [${l.entity}].[${l.key}] = ${l.keyValue})` : '';
  if (l.exact) return `- ${ref} = ${sqlLit(l.value)}${key}\n`;
  if (l.count === 1) return `- ${ref}: the only stored value containing ${sqlLit(l.phrase)} is ${sqlLit(l.samples[0])}${key}\n`;
  return `- ${ref}: ${l.count} stored values contain ${sqlLit(l.phrase)}, e.g. ${l.samples.map(sqlLit).join(', ')}`
    + ` -> LIKE ${sqlLit('%' + l.phrase + '%')} if the question means all of them\n`;
}
const VALUES_HEADER = '\nVALUES FROM THE QUESTION (spelled exactly as stored in the database; filter with these, not with your own spelling):\n';

const metricLine = m => `- ${m.name_fa} = ${m.sql}`
  + (m.filter ? `   (always filter: ${m.filter})` : '')
  + (m.note_fa ? `   -- ${m.note_fa}` : '') + '\n';
const METRICS_HEADER = '\nMETRICS (when the question asks for one of these, use exactly this definition):\n';

// ---------- تعریف یک جدول (CREATE TABLE) با توضیح فارسی و نمونه مقدار ستون‌ها ----------
function ddlOf(ent) {
  const cols = ent.columns;
  const lines = cols.map((c, idx) => {
    const nm   = c.alias || c.name;
    const last = idx === cols.length - 1;
    const ex   = c.samples;
    const vals = ex ? `${c.description_fa ? '; ' : ''}values: ${ex.map(v => sqlLit(String(v).slice(0, 30))).join(', ')}` : '';
    const d    = c.description_fa || vals ? `   -- ${c.description_fa || ''}${vals}` : '';
    return `  [${nm}] ${c.type || 'nvarchar'}${last ? '' : ','}${d}`;
  });
  const head = ent.description_fa
    ? `CREATE TABLE [${ent.name}] (   -- ${ent.description_fa}`
    : `CREATE TABLE [${ent.name}] (`;
  return `${head}\n${lines.join('\n')}\n);\n`;
}

const relLine      = j => `-- [${j.from}].[${j.from_column}] = [${j.to}].[${j.to_column}]\n`;
const hintLine     = h => '- ' + h + '\n';
const HINTS_HEADER = '\nDOMAIN NOTES:\n';

// ---------- متن کامل prompt ----------
// برای تغییر قوانین یا متن prompt فقط همین تابع را عوض کنید. متن فقط اینجا ساخته می‌شود؛ هم برای
// اندازه‌گیری بخش ثابت و هم برای خروجی نهایی، پس بودجه دقیقاً همان چیزی را می‌شمارد که به مدل می‌رسد.
function renderPrompt({ question, lowConfidence, hints, examples, schema, rels, values = [], metrics = [], today = '', rules = [] }) {
  return `You are a Microsoft SQL Server (T-SQL) expert.

Your response must have EXACTLY this shape and nothing else:
UNDERSTOOD: <one concise English sentence restating what the question is asking for - always in English, even though the question may be in Persian>
PLAN:
- tables: <the entities needed and the relationship used to join each one>
- filters: <the WHERE conditions, using the exact values/keys from VALUES and the filters from METRICS>
- result: <what is selected and aggregated, GROUP BY, ORDER BY, TOP N>
SQL:
<a single T-SQL SELECT query that follows the PLAN - no markdown fences, no explanation>

RULES:
- Microsoft SQL Server. Use SELECT TOP N. NEVER use LIMIT.
- TOP comes immediately after SELECT.
- The entities below are ready-made views. Query them directly.
- Use ONLY these entities, columns and relationships. Names EXACTLY as listed, in [square brackets].
- Write every Persian (or any non-English) string literal with the N prefix: N'تهران', never 'تهران'.
${today}${rules.map(r => `- ${r}\n`).join('')}- The question may be written in Persian. Understand it, but respond only with SQL.
- Write the PLAN first and check it against the entities, relationships and notes below; then write SQL that does exactly what the PLAN says. Keep the PLAN to the three short lines.
- If the question needs a table, column or business concept that is NOT among the entities/columns below, do NOT substitute a similar-looking one and do NOT guess. Respond instead with exactly this shape (no PLAN needed):
UNDERSTOOD: <state in English what data would be needed and that it is not available>
SQL:
SELECT 'NOT_SUPPORTED' AS Status, 'briefly say in English what is missing' AS Reason
${lowConfidence ? '\nNOTE: none of the available entities scored as a strong semantic/keyword match for this question, so it is likely NOT answerable with the schema below. Prefer the NOT_SUPPORTED response above unless one of these entities genuinely answers the question.\n' : ''}${hints.length ? HINTS_HEADER + hints.map(hintLine).join('') : ''}${metrics.length ? METRICS_HEADER + metrics.map(metricLine).join('') : ''}${values.length ? VALUES_HEADER + values.map(valueLine).join('') : ''}
${examples.length ? 'Examples of correct SQL for similar questions (only the SQL part is shown):\n' : ''}${examples.map((ex, i) => `Example ${i + 1}:\nQ: ${ex.q}\nSQL: ${ex.sql}`).join('\n\n')}

Available entities:
${schema}Relationships:
${rels}
Q: ${question}
A:`;
}

// ---------- مرحله ۱. جا دادن جدول‌ها در بودجه ----------
// هزینه هر جدول = DDL خودش + خطوط رابطه‌ای که با جدول‌های قبلاً پذیرفته‌شده اضافه می‌کند
// + راهنماهای مخصوص آن جدول. بخش ثابت (قوانین، راهنماهای حوزه، مثال‌ها، سوال) یک‌بار از
// بودجه کم می‌شود؛ اگر راهنمای حوزه‌ای نباشد، جای سرتیتر DOMAIN NOTES برای راهنماهای مخصوص
// جدول‌ها رزرو می‌شود. جدول‌ها به ترتیب امتیاز پذیرفته می‌شوند و اولین جدول همیشه (حتی اگر
// به‌تنهایی از بودجه بزرگ‌تر باشد).
function packPrompt(plan, today) {
  const { question, lowConfidence, joins, examples, values, metrics } = plan;
  const rules = plan.rules || [];   // از یادداشت Obsidian «Rules for every question»
  const fixed = renderPrompt({ question, lowConfidence, hints: plan.hints.domain, today, rules,
                               examples, values, metrics, schema: '', rels: '' });
  let budget = CFG.MAX_PROMPT_CHARS - fixed.length - (plan.hints.domain.length ? 0 : HINTS_HEADER.length);

  const finalTables = [];
  const nameSet    = new Set();
  const seenRel    = new Set();
  const hintSet    = new Set();
  const hints      = [...plan.hints.domain];
  let schema = '', rels = '';

  for (const table of plan.tables) {
    const name = table.name;
    const ddl = ddlOf(table) + '\n';
    const newRels = [];
    for (const j of joins) {
      const touches = (j.from === name && (nameSet.has(j.to) || j.to === name))
                   || (j.to === name && nameSet.has(j.from));
      if (!touches) continue;
      const line = relLine(j);
      if (!seenRel.has(line) && !newRels.includes(line)) newRels.push(line);
    }
    const newHints = plan.hints.scoped.filter(h => !hintSet.has(h) && (h.entities || []).includes(name));
    const cost = ddl.length + newRels.join('').length + newHints.map(h => hintLine(h.text)).join('').length;
    if (cost > budget && finalTables.length > 0) continue;

    budget -= cost;
    schema += ddl;
    newRels.forEach(l => { seenRel.add(l); rels += l; });
    newHints.forEach(h => { hintSet.add(h); hints.push(h.text); });
    nameSet.add(name);
    finalTables.push(table);
  }

  // ---------- مرحله ۲. مثال/مقدار/معیاری که جدولش جا نماند حذف می‌شود (فقط جا آزاد می‌کند) ----------
  const kept = examples.filter(e => e.entities.every(n => nameSet.has(n)));
  const keptValues = values.filter(l => nameSet.has(l.entity));
  const keptMetrics = metrics.filter(m => m.entities.every(n => nameSet.has(n)));
  const prompt = renderPrompt({ question, lowConfidence, hints, today, rules, examples: kept,
                                values: keptValues, metrics: keptMetrics, schema, rels });
  return { finalTables, prompt, examples: kept, values: keptValues, metrics: keptMetrics };
}

// ---------- مرحله ۳. تعریف جدول‌ها برای Security ----------
// Security از روی همین فهرست CTE می‌سازد؛ فقط ستون‌های قابل نمایش (همان‌هایی که مدل دیده).
function toEntityDefs(tables) {
  const defs = {};
  for (const t of tables) {
    defs[t.name] = {
      name:    t.name,
      kind:    t.kind || 'table',
      source:  t.source || null,
      sql:     t.sql || null,
      columns: t.columns.map(c => ({ name: c.name, alias: c.alias || null }))
    };
  }
  return defs;
}

// ==================== اجرای مراحل ====================
function buildPrompt({ plan, now }, log) {
  if (plan.refusal) throw new Error(plan.refusal);   // پیام ⛔ سرویس، برای کاربر (ErrorFormat)
  const packed = packPrompt(plan, todayLine(now || new Date()));
  const { finalTables, prompt } = packed;
  const finalNames = finalTables.map(t => t.name);
  const r = plan.retrieval || {};

  log('EXAMPLES | ' + (packed.examples.map(e => `${e.id}(lex ${e.lex.toFixed(2)}`
    + (e.sem === null ? '' : ` sem ${e.sem.toFixed(2)}`) + ')').join(' | ') || 'none'));
  if (prompt.length > CFG.MAX_PROMPT_CHARS) {
    // فقط وقتی رخ می‌دهد که اولین جدول به‌تنهایی از بودجه بزرگ‌تر باشد
    log('PROMPT OVER BUDGET | chars=' + prompt.length + ' | max=' + CFG.MAX_PROMPT_CHARS);
  }
  log('SELECTED | ' + finalNames.join(', ') + ' | promptChars=' + prompt.length
    + ' | semanticUsed=' + Boolean(r.semanticUsed)
    + ' | topScore=' + Number(r.topScore || 0).toFixed(2)
    + ' | lowConfidence=' + Boolean(plan.lowConfidence));

  return {
    body: { string1: '-', string2: prompt },
    question: plan.question,
    selectedEntities: finalNames,
    entityDefs: toEntityDefs(finalTables),
    promptChars: prompt.length,
    retrieval: Object.assign({}, r, {
      examples: packed.examples.map(e => ({ id: e.id, sem: e.sem, lex: e.lex })),
      metrics: packed.metrics.map(m => m.name_fa),
      values: packed.values.map(l => ({ entity: l.entity, column: l.column, exact: l.exact,
                                        value: l.exact ? l.value : null, phrase: l.exact ? null : l.phrase }))
    })
  };
}

// ==================== خروجی n8n ====================
return [{ json: buildPrompt(readN8nInputs(), msg => console.log(msg)) }];

// ===== ErrorFormat: پیام خطا برای کاربر =====
// ورودی:  خطای هر نودی که شکست خورد (LDAP، AuthCheck، Find Tables / Ask Notes (catalog-service)، BuildPrompt، Security، اجرای SQL، ...)
// خروجی:  { answer }؛ در حالت ارزیابی (بنچمارک) { answer, error, selectedEntities }
// پیام‌هایی که با ⛔ شروع می‌شوند برای کاربر نوشته شده‌اند و همیشه نشان داده می‌شوند. خطای فنی (پیام SQL Server،
// نام جدول و ستون) فقط به کسی که اجازه seeDetails دارد نشان داده می‌شود (AuthCheck)؛ بقیه پیام عمومی می‌بینند.
// بعد از این نود: Respond to Webhook (جواب کاربر) و Obsidian note (یادداشت «سوال بی‌جواب»).

const GENERIC = '⛔ در پردازش درخواست شما خطایی رخ داد.\n\nلطفاً سوال را به شکل دیگری بپرسید. اگر تکرار شد با واحد فناوری اطلاعات تماس بگیرید.';

// ---------- ۱. آداپتر n8n: تنها جایی که $input و $('...') خوانده می‌شود ----------
// نودی که اجرا نشده (مثلاً خطای LDAP پیش از AuthCheck) یعنی «هیچ اجازه‌ای نیست»
function readN8nInputs() {
  const json = name => { try { return $(name).first().json || {}; } catch (e) { return {}; } };
  return {
    error: $input.first().json,
    can: json('AuthCheck').can || {},
    selectedEntities: json('BuildPrompt').selectedEntities || [],
  };
}

// ---------- ۲. منطق ----------
function errorText(e) {
  const raw = (e.error && (e.error.message || e.error)) || e.message || '';
  return String(raw).replace(/\s*\[line \d+\]\s*$/i, '').trim();
}

function formatError({ error, can, selectedEntities }) {
  const raw = errorText(error);
  const answer = (raw.startsWith('⛔') || (can.seeDetails && raw)) ? raw : GENERIC;
  // در حالت ارزیابی، runner بنچمارک خطا را از فیلد error می‌شناسد (رد شدن سوال امنیتی = موفقیت) و
  // selectedEntities خطای retrieval را از خطای SQL جدا می‌کند
  return can.evalMode ? { answer, error: raw || answer, selectedEntities } : { answer };
}

// ---------- ۳. اجرا ----------
return [{ json: formatError(readN8nInputs()) }];

// ===== AuthCheck: کاربر کیست، عضو کدام گروه‌هاست و چه اجازه‌هایی دارد؟ =====
// ورودی:  نتیجه نود LDAP (جست‌وجوی ایمیل کاربر) + ایمیل، نام و هدرهای درخواست (Webhook)
// خروجی:  { username, email, groups, can: { seeDetails, evalMode, reviewNotes, projectNotes } }
//   groups - نام گروه‌ها (CN)، مثل «IT - Data» یا «NLSQL-sales». Find Tables با همین نام‌ها و permissions
//            کاتالوگ‌ها تعیین می‌کند کاربر کدام جدول‌ها را ببیند.
//   can    - اجازه‌های غیر از جدول‌ها، فقط همین‌جا تعیین می‌شوند (جدول RIGHTS پایین). نودهای بعدی
//            (ErrorFormat، Format Answer، Obsidian note، و catalog-service برای جست‌وجوی یادداشت‌ها) فقط can را می‌خوانند و نام هیچ گروهی را نمی‌دانند.
// ⚠️ ایمیل از بدنه درخواست خوانده می‌شود و به آن اعتماد می‌شود (ورود در OpenWebUI انجام شده). تا وقتی
//    Webhook با Header Auth بسته نشده، هر کسی که به آدرس webhook دسترسی دارد می‌تواند ایمیل دیگری بفرستد.

// ---------- تنظیمات: چه کسی چه کاری می‌تواند بکند ----------
// نام گروه‌ها باید دقیقاً مثل AD باشد (با فاصله‌ها).
const RIGHTS = {
  seeDetails:  ['IT - Data', 'IT - Security'],   // متن خطای فنی (SQL Server، نام جدول) را ببیند
  evalMode:    ['IT - Data'],                    // بنچمارک: با هدر x-eval-mode: true ردیف‌ها و SQL را هم بگیرد
  reviewNotes: ['IT - Data', 'IT - Security'],   // برای هر جوابش یادداشت ✅/❌ در Obsidian نوشته شود
  projectNotes: ['IT - Data', 'IT - Security'],  // مدل «Obsidian notes» از یادداشت‌های پروژه (Home، How-to، Schema، ...) هم جواب بدهد؛
                                                 // یادداشت‌های کاتالوگ را همه با همان permissions کاتالوگ می‌بینند
};

// ---------- ۱. آداپتر n8n: تنها جایی که $input و $('...') خوانده می‌شود ----------
function readN8nInputs() {
  const wh = $('Webhook').first().json;
  return {
    body: wh.body || {},
    headers: wh.headers || {},
    entries: $input.all().map(i => i.json).filter(e => e && Object.keys(e).length > 0),
  };
}

// ---------- ۲. منطق ----------
function directoryEntry(entries, identity) {
  if (entries.length === 0) throw new Error('⛔ کاربر در دایرکتوری یافت نشد: ' + identity);
  // چند رکورد برای یک ایمیل یعنی داده‌ی دایرکتوری مبهم است — نباید حدس بزنیم
  if (entries.length > 1) throw new Error('⛔ چند رکورد برای این کاربر در دایرکتوری یافت شد. با تیم IT تماس بگیرید.');
  return entries[0];
}

// «CN=IT - Data,OU=...» ← «IT - Data»
function groupNames(memberOf) {
  const list = typeof memberOf === 'string' ? [memberOf] : (memberOf || []);
  return list.map(dn => (String(dn).match(/^CN=([^,]+)/i) || [])[1]).filter(Boolean);
}

function rightsOf(groups, headers) {
  const inAny = names => groups.some(g => names.includes(g));
  return {
    seeDetails: inAny(RIGHTS.seeDetails),
    evalMode: String(headers['x-eval-mode'] || '').toLowerCase() === 'true' && inAny(RIGHTS.evalMode),
    reviewNotes: inAny(RIGHTS.reviewNotes),
    projectNotes: inAny(RIGHTS.projectNotes),
  };
}

function authCheck({ body, headers, entries }) {
  const identity = (body.email || '').trim().toLowerCase();
  if (!identity) throw new Error('⛔ ایمیل کاربر دریافت نشد. ورود به OpenWebUI باید از طریق LDAP باشد.');
  const e = directoryEntry(entries, identity);
  const groups = groupNames(e.memberOf);
  return { username: e.sAMAccountName || body.username || '', email: identity, groups, can: rightsOf(groups, headers) };
}

// ---------- ۳. اجرا ----------
return [{ json: authCheck(readN8nInputs()) }];

// ===== Build Fix Prompt: SQL خطادار + پیام خطای SQL Server را برای اصلاح به مدل برمی‌گرداند =====
// ورودی:  خطای نود «execute query» (از راه «Retry once?»)؛ SQL مدل (Security) و prompt اصلی (BuildPrompt)
// خروجی:  { body: { string1, string2 } } برای همان «request to LLM» - همان شکل BuildPrompt، پس بقیه مسیر
//          (Security، execute query) فرقی بین تلاش اول و دوم نمی‌گذارد. Security از اجرا شدن همین نود
//          می‌فهمد که تلاش دوم است (attempt = 2) و «Retry once?» خطای دوم را به ErrorFormat می‌فرستد.

const MAX_ERROR_CHARS = 1000;

// ---------- ۱. آداپتر n8n: تنها جایی که $input و $('...') خوانده می‌شود ----------
function readN8nInputs() {
  const sec = $('Security').first().json;
  return {
    error: $input.first().json,
    // SQL خام مدل (modelSql) نه نسخه پیچیده‌شده در CTE (sql)، تا prompt اصلاح همان شکلی باشد که مدل نوشت
    failedSql: sec.modelSql || sec.sql || '',
    // همان prompt اصلی (جدول‌ها، قواعد، سوال) تا مدل دوباره همه زمینه را داشته باشد
    originalPrompt: $('BuildPrompt').first().json.body.string2,
  };
}

// ---------- ۲. منطق ----------
function errorText(e) {
  return String((e.error && (e.error.message || e.error)) || e.message || JSON.stringify(e)).slice(0, MAX_ERROR_CHARS);
}

function fixPrompt({ error, failedSql, originalPrompt }) {
  return `${originalPrompt}

Your previous answer was:
${failedSql}

Running it against Microsoft SQL Server failed with this error:
${errorText(error)}

Fix the query so it runs successfully. Reply in the exact same shape as before:
UNDERSTOOD: <English sentence>
PLAN:
- error: <what in the previous query caused this error>
- tables / filters / result: <the corrected plan, in one or two short lines>
SQL:
<the corrected T-SQL SELECT query>
Use ONLY the listed entities and columns with their exact names. No markdown fences, no other text.`;
}

// ---------- ۳. اجرا ----------
return [{ json: { body: { string1: '-', string2: fixPrompt(readN8nInputs()) } } }];

// ===== Obsidian note: یک یادداشت در obsidian/Inbox/n8n برای بازبینی =====
// این نود و «Save to Obsidian Inbox» تنها جای workflow هستند که با Obsidian کار دارند. n8n از Obsidian چیزی
// نمی‌خواند؛ فقط یک فایل Markdown در پوشه‌ای می‌نویسد که در docker-compose.yml به obsidian/Inbox/n8n وصل است.
// دو حالت (شاخه کناری است، بعد از جواب کاربر اجرا می‌شود و جواب را تغییر نمی‌دهد):
//   ۱. سوالی که جواب نگرفت (بعد از ErrorFormat)   ← برای همه کاربران؛ با فهرست کارهای لازم
//   ۲. سوالی که جواب گرفت (بعد از Format Answer)   ← فقط برای کسی که اجازه reviewNotes دارد (AuthCheck)؛
//      با دو گزینه ✅ / ❌. بازبین فقط تیک می‌زند و scripts/learn-from-inbox.js جواب‌های ✅ را به مثال
//      تأییدشده و سوال بنچمارک تبدیل می‌کند؛ لازم نیست کسی SQL بنویسد.
// نام و ایمیل کاربر نوشته نمی‌شود. اجراهای بنچمارک (حالت ارزیابی) یادداشت نمی‌سازند.

const INBOX = '/home/node/.n8n-files/obsidian-inbox';   // داخل کانتینر n8n = obsidian/Inbox/n8n روی سرور
const ANSWER_LINES = 25;                                 // چند خط از جواب در یادداشت بیاید

// ---------- ۱. آداپتر n8n: تنها جایی که $input و $('...') خوانده می‌شود ----------
function readN8nInputs() {
  const ran = name => { try { $(name).first(); return true; } catch (e) { return false; } };
  const json = name => { try { return $(name).first().json || {}; } catch (e) { return {}; } };
  return {
    out: $input.first().json,
    answered: ran('Format Answer'),
    can: json('AuthCheck').can || {},
    question: String((json('Webhook').body || {}).question || ''),
    bp: json('BuildPrompt'),
    sec: json('Security'),
    now: new Date(),
  };
}

// ---------- ۲. منطق ----------
function wantsNote({ out, answered, can }) {
  if (out.error !== undefined || out.rows !== undefined) return false;   // حالت ارزیابی (بنچمارک)
  return !answered || Boolean(can.reviewNotes);
}

// بخش‌های مشترک هر دو نوع یادداشت
function noteParts({ out, question, bp }) {
  const r = bp.retrieval || {};
  const why = r.why || {};
  return {
    r,
    title: question.replace(/\s+/g, ' ').slice(0, 120) || '(no question)',
    tables: (bp.selectedEntities || []).map(n => `- [[${n}]] - ${(why[n] || []).join('، ')}`).join('\n') || '- (none)',
    answerText: String(out.answer || '').replace(/<think>[\s\S]*?<\/think>\s*/g, '').trim(),
  };
}

function answeredNote(input) {
  const { question, bp, sec, now } = input;
  const { r, title, tables, answerText } = noteParts(input);
  // داده لازم برای learn-from-inbox.js، در یک کامنت Obsidian (در حالت خواندن دیده نمی‌شود)؛ base64 تا % یا
  // نویسه‌های دیگر SQL کامنت را نشکنند
  const data = {
    question,
    model_sql: sec.modelSql || '',
    sql: sec.sql || '',
    entities: bp.selectedEntities || [],
    used: sec.entities || [],
    domains: r.activeDomains || []
  };
  return `---
type: answered-question
status: to-review
date: ${now.toISOString().slice(0, 10)}
domains: [${(r.activeDomains || []).join(', ')}]
---
# ${title}

Is this answer right? Tick ONE box. Then run \`node scripts/learn-from-inbox.js\` (How-to → Review answers).
- [ ] ✅ correct
- [ ] ❌ wrong

**Understood as:** ${sec.understood || '-'}

## Answer
${answerText.split('\n').slice(0, ANSWER_LINES).join('\n')}

## Tables the model was given
${tables}

## If it is wrong
- A needed table is missing above? Add the user's word to \`synonyms_fa\` of that table.
- Wrong number (sum, filter, status)? Add or fix a metric in the catalog.

%% text2sql ${Buffer.from(JSON.stringify(data), 'utf8').toString('base64')} %%
`;
}

function failedNote(input) {
  const { now } = input;
  const { r, title, tables, answerText } = noteParts(input);
  return `---
type: failed-question
status: open
date: ${now.toISOString().slice(0, 10)}
domains: [${(r.activeDomains || []).join(', ')}]
low_confidence: ${Boolean(r.lowConfidence)}
---
# ${title}

**Answer sent:** ${answerText.split('\n')[0]}

## Tables the model was given
${tables}

## What to do
- [ ] Wrong or missing table? Add the user's word to \`synonyms_fa\` of the right table
- [ ] Right table, wrong SQL? Add a metric, a hint or a query-bank example
- [ ] Really not answerable? Nothing to fix
- [ ] Then delete this note
`;
}

// آیتم n8n برای نود «Save to Obsidian Inbox»: مسیر فایل + محتوای آن به شکل binary
function noteFile(input) {
  const stamp = input.now.toISOString().slice(0, 19).replace('T', ' ').replace(/:/g, '');   // 2026-10-10 142233
  const name = `${stamp} ${input.answered ? 'answered' : 'failed'} question.md`;
  const md = input.answered ? answeredNote(input) : failedNote(input);
  return {
    json: { path: `${INBOX}/${name}` },
    binary: { data: { data: Buffer.from(md, 'utf8').toString('base64'), mimeType: 'text/markdown', fileName: name } }
  };
}

// ---------- ۳. اجرا ----------
const input = readN8nInputs();
return wantsNote(input) ? [noteFile(input)] : [];
